#!/usr/bin/env python3
"""Parse a JSONL file, extract categorical columns, and output an HTML table."""

import json
import sys
from pathlib import Path


def load_jsonl(path: str) -> list[dict]:
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


def find_categorical_columns(rows: list[dict], max_unique_ratio: float = 0.5) -> list[str]:
    """Return column names that look categorical (non-numeric or low cardinality)."""
    if not rows:
        return []

    all_keys = list(rows[0].keys())
    categorical = []

    for key in all_keys:
        values = [r.get(key) for r in rows if r.get(key) is not None]
        if not values:
            continue

        # Non-numeric types are categorical
        non_numeric = any(isinstance(v, str) for v in values)
        if non_numeric:
            categorical.append(key)
            continue

        # Numeric but low cardinality relative to row count
        unique_ratio = len(set(map(str, values))) / len(values)
        if unique_ratio <= max_unique_ratio:
            categorical.append(key)

    return categorical


def rows_to_html_table(rows: list[dict], columns: list[str]) -> str:
    lines = ["<table>", "  <thead>", "    <tr>"]
    for col in columns:
        lines.append(f"      <th>{col}</th>")
    lines.append("    </tr>")
    lines.append("  </thead>")
    lines.append("  <tbody>")
    for row in rows:
        lines.append("    <tr>")
        for col in columns:
            val = row.get(col, "")
            lines.append(f"      <td>{val}</td>")
        lines.append("    </tr>")
    lines.append("  </tbody>")
    lines.append("</table>")
    return "\n".join(lines)


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <input.jsonl> [output.html]", file=sys.stderr)
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2] if len(sys.argv) > 2 else None

    rows = load_jsonl(input_path)
    if not rows:
        print("No rows found in input file.", file=sys.stderr)
        sys.exit(1)

    categorical_cols = find_categorical_columns(rows)
    if not categorical_cols:
        print("No categorical columns detected.", file=sys.stderr)
        sys.exit(1)

    print(f"Categorical columns: {categorical_cols}", file=sys.stderr)

    html = rows_to_html_table(rows, categorical_cols)

    if output_path:
        Path(output_path).write_text(html, encoding="utf-8")
        print(f"Wrote {output_path}", file=sys.stderr)
    else:
        print(html)


if __name__ == "__main__":
    main()
